quests[89260] = { id = 89260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove Your Worth: Belt", description = "Staying on top of your trade is crucial for maintaining a high standard of quality. Our soldiers entrust their lives to unnamed craftsmen, and to me for ensuring the quality of every piece of armor.\n\nMy task for you is simple. If you are well practiced in Tailoring, Leatherworking, or Blacksmithing, then craft a belt, purely for your own benefit. You are free to keep the result.\n\nIf you lack the skill, commission and donate any piece of the crusade's uniform instead.", sourceObjective = "Craft a Scarlet Belt from any armor crafting profession or donate any piece of crafted Scarlet Uniform equipment. \n\nIf you choose to donate, you can find a crate near the quartermaster inside of the barracks. Deliver the crated item back to Bryon Steelblade to receive credit.", progress = "Craft or contribute; the choice is yours. Our armory is well equipped for whatever comes our way, but the important thing is ensuring our craftsmen have ample opportunities to practice and refine their technique.", completion = "Excellently done.\n\nWe have started stashing confiscated junk in these old trunks and I am running out of space to store them now, but you seem the sort to take value in the little things. I believe this is an appropriate reward for a single contribution.\n\nOh, and I added a valuable surprise into a few of these. Maybe you'll be one of the lucky ones?", sourceObjectiveStatus = "unverified-source-field" }
quests[89261] = { id = 89261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove Your Worth: Legguards", description = "Staying on top of your trade is crucial for maintaining a high standard of quality. Our soldiers entrust their lives to unnamed craftsmen, and to me for ensuring the quality of every piece of armor.\n\nMy task for you is simple. If you are well practiced in Tailoring, Leatherworking, or Blacksmithing, then craft a pair of trousers, purely for your own benefit. You are free to keep the result.\n\nIf you lack the skill, commission and donate any piece of the crusade's uniform instead.", sourceObjective = "Craft a pair of Scarlet Pants from any armor crafting profession or donate any piece of crafted Scarlet Uniform equipment. \n\nIf you choose to donate, you can find a crate near the quartermaster inside of the barracks. Deliver the crated item back to Bryon Steelblade to receive credit.", progress = "Craft or contribute; the choice is yours. Our armory is well equipped for whatever comes our way, but the important thing is ensuring our craftsmen have ample opportunities to practice and refine their technique.", completion = "Excellently done.\n\nWe have started stashing confiscated junk in these old trunks and I am running out of space to store them now, but you seem the sort to take value in the little things. I believe this is an appropriate reward for a single contribution.\n\nOh, and I added a valuable surprise into a few of these. Maybe you'll be one of the lucky ones?", sourceObjectiveStatus = "unverified-source-field" }
quests[89262] = { id = 89262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove Your Worth: Boots", description = "Staying on top of your trade is crucial for maintaining a high standard of quality. Our soldiers entrust their lives to unnamed craftsmen, and to me for ensuring the quality of every piece of armor.\n\nMy task for you is simple. If you are well practiced in Tailoring, Leatherworking, or Blacksmithing, then craft a pair of footwear, purely for your own benefit. You are free to keep the result.\n\nIf you lack the skill, commission and donate any piece of the crusade's uniform instead.", sourceObjective = "Craft a pair of Scarlet Boots from any armor crafting profession or donate any piece of crafted Scarlet Uniform equipment. \n\nIf you choose to donate, you can find a crate near the quartermaster inside of the barracks. Deliver the crated item back to Bryon Steelblade to receive credit.", progress = "Craft or contribute; the choice is yours. Our armory is well equipped for whatever comes our way, but the important thing is ensuring our craftsmen have ample opportunities to practice and refine their technique.", completion = "Excellently done.\n\nWe have started stashing confiscated junk in these old trunks and I am running out of space to store them now, but you seem the sort to take value in the little things. I believe this is an appropriate reward for a single contribution.\n\nOh, and I added a valuable surprise into a few of these. Maybe you'll be one of the lucky ones?", sourceObjectiveStatus = "unverified-source-field" }
quests[89300] = { id = 89300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashbringer", description = "Your hand trembles as it closes on the hilt of the shattered blade. You hold the remnants of a truly legendary weapon, the Ashbringer. Holding what remains of the sword fills you with a sense of icy dread, and you could swear that you hear voices in your mind. One voice in particular rings the loudest. \n\n<If you would see it restored, take up the broken blade. This road may only lead to damnation, but I will show you the way.>", sourceObjective = "Equip the Hilt of the Ashbringer and use the blade to commune with the disembodied spirit you hear in your head.\n\nProvided item:", completion = "Good, you have taken the first step. \n\nI am an echo of the original owner of the Ashbringer. Something of a... witness to the folly of those who think that simply wielding legendary weapons will make themselves legendary. Caldoran fell into this trap, and oblivion was his reward.\n\nAs for you, perhaps you could be different? You could do better. Or you could fail like so many others, and reach for power over principle in the same vainglorious aspirations.", sourceObjectiveStatus = "unverified-source-field" }
quests[89301] = { id = 89301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Difficult Path", description = "There is a fount of great power residing at the base of the World Tree, high atop Mount Hyjal. This is a place of ancient and storied history; it was recently the focus of the final clash between the defenders of Azeroth and the Burning Legion. It is now a haunted place, steeped in the power of light and shadow... life and death. \n\nThis power mirrors the duality of the blade and we will see the weapon tempered there. Reaching the summit of the mountain will be no small feat, however.", sourceObjective = "Speak with the Will of the Ashbringer to learn what is needed to access the peak of Mount Hyjal.", progress = "The original blade was tempered in the the blood of a nation falling to flame, war, and darkness. There's ancient, and eldritch magic in such things.", completion = "The druids have jealously guarded the secrets of Hyjal since the end of the Third War. They are not your only obstacle, however. Scourge remnants, wilds gods, demons... even dragons stalk the mountainside. With luck, an  opportunity will present itself that will allow you to bypass those dangers. \n\nWe can but hope that fortune will smile upon you.", sourceObjectiveStatus = "unverified-source-field" }
quests[89303] = { id = 89303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Fate's Path", description = "Caldoran used a combination of holy magic, skilled craftsmanship, and ambition to \"cleanse\" the blade.  The Ashbringer ultimately rejected Caldoran, but some of his methods may have some merit as a place to start. \n\nLight and darkness are the sum of what the Ashbringer is now and the lightforged weapons wielded by the crusaders in the  Enclave may be of use to us.", sourceObjective = "Find Omarion inside of the Scarlet Enclave and ask him how the work on his new lightforged alloy is going.\n\nSpeak with the Will of the Ashbringer when you have what you need.", progress = "What have you discovered, {class}?", completion = "The methods of the Scarlet Crusade are as twisted as they are misguided.  The arms and armor of the crusaders shine with radiant light, but also reflect the inherent darkness of the Scarlet Crusade. The inherent duality of this lightforged metal makes it well suited to reforging the blade.\n\nOnly one component remains.", sourceObjectiveStatus = "unverified-source-field" }
quests[89304] = { id = 89304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Metal", description = "Now that we've got the materials, I need a bit of time to try a few different combinations and test my results. This is delicate work, and I wouldn't want to waste any of the materials that you so graciously brought me by testing too hastily.", sourceObjective = "Talk to Omarion about what comes next.", completion = "I'll be fine here on my own. In the meantime, start thinking about what kind of weapon you want made. If you find yourself suddenly inspired, feel free to return here and let me know. \n\nOh, and thank you, {name}. As much as I hate to admit it, having something like this to dig into has done me a lot of good. I'm still not sure if I'll ever rejoin the Argent Dawn, but at least I'm not moping around in that cage anymore. \n\nOh, and take this. It isn't much but its a token of my appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[89310] = { id = 89310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrordale", description = "It took me many years to recover from my guilt once my mind was set free from the Lich King. Once liberated by Sylvanas, I rejected the Dark Lady's offer and walked into the plaguelands alone. I wandered for months aimlessly. I'm not sure why I did it but eventually I found my way back to my family's home and what I found there was... unexpected.\n\nTravel to the haunted village now known as Terrordale, find the northernmost house and meet me there. You'll learn the rest.", sourceObjective = "Travel to Terrordale and find Leonid Barthalomew the Revered at one of the houses there.", completion = "It sickens me to see what has become of my home.", sourceObjectiveStatus = "unverified-source-field" }
quests[89328] = { id = 89328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loss", description = "When my meandering brought me here you can imagine my surprise to find my son alive and well. He did not reject me as the other living did, he embraced me. He had become a healer, and was studying the undead. He was convinced that he could find a cure to not only prevent undeath, but reverse it. \n\nFor a short time, we were together and happy. I helped my son with his research, and he gave me the hope I needed.\n\nThat is, until Baelin Caldoran rode back into our lives.", sourceObjective = "Hear the final part of Leonid's story.", completion = "Much to my shame, I survived. Not long after this Lord Tyrosus found me and patched me up. \n\nNot once, but twice was Baelin Caldoran responsible for the death of someone dear to me. His brand of arrogant bigotry is the very heart of the corruption that plagues the Scarlet Crusade. \n\nWhile I'll never recover from the pain, I still honor my son by sharing his hope and vision for a future where the curse of undeath can be cured. I have to hope that someday, someone will be able to finish my son's work.", sourceObjectiveStatus = "unverified-source-field" }
quests[89329] = { id = 89329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stomping Out The Infestation", description = "Disgusting. This place has become infested with rotting nerubian drones. I would see them destroyed.", sourceObjective = "Slay 5 Crypt Walkers and 8 Crypt Fiends then return to Leonid Barthalomew the Revered at his former home in Terrordale.", completion = "It's more than likely a meaningless gesture, but I feel at least a tiny bit better.", sourceObjectiveStatus = "unverified-source-field" }
quests[89340] = { id = 89340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preposterously Prosed Postage", description = "To the Esteemed Head Chef of New Avalon: Carrie Hearthfire,\n\nI trust this letter finds you in good spirits! Your departure from Hearthglen has left a hole in our hearts, and in our stomachs. Not a day passes by without a complaint of the morning gruel, yearning for the next delightful meal.\n\nTo that end we are planning a banquet; one which we intend to serve only the finest dishes in Lordaeron: yours.\n\nAn escorted caravan will arrive in a fortnight. You and your meals ought best be prepared.", sourceObjective = "Finish the delivery.", completion = "<Carrie ultimately takes the letter after your insistence and skims the contents. Her eyes go wide.>\n\nHow am I supposed to gather the ingredients and prepare meals for an entire sect of the Scarlet Crusade... in less than two weeks? Truly terrible timing.\n\nWhatever the case, the citizens of New Avalon come first. In the meantime I must hope for a helping hand, I suppose.\n\n<She pauses.>\n\nWait a minute, why was this already opened?", sourceObjectiveStatus = "unverified-source-field" }
quests[89341] = { id = 89341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Feast", description = "Your assistance has been invaluable. The citizens and soldiers of New Avalon can count on a hot meal tonight, and for many nights that follow. You have my gratitude, truly.\n\nHowever, as you apparently read yourself, I have one last task to tend to before I can finally put my feet up. I can handle most of this myself, but if you're willing to do me one more favor, I will teach you my most famous recipes.\n\nYou will be eating like a Highlord every night.", sourceObjective = "Aid Carrie Hearthfire in New Avalon one last time by gathering the following ingredients:", progress = "Ah, it is wonderful to see you again. Have you brought me the last batch of ingredients I need?", completion = "Fast and reliable as always, I can't believe I ever doubted you. Allow me to take these off your hands.\n\nYour motivations are still unclear to me but, it is apparent that you have a kind heart. As promised, here is my cookbook. I don't need it anymore, I have long since memorized all of my recipes.\n\nThank you again, and don't be a stranger.\n\n<Carrie offers a sincere, relaxed smile before resuming her work.>", sourceObjectiveStatus = "unverified-source-field" }
quests[89342] = { id = 89342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "VIP Haute Club Membership", description = "Hey, you!\n\nYou look like the person Carrie had been speaking of recently. She said many good things about you. Well, not at first, but she quickly changed her tone.\n\nAnyway, friends of the chef are friends of mine. I'd like to grant you a permanent membership, and you won't need to carry that card around all the time.\n\nAll I ask in return is a Sunrise Omelette and a Prowler Steak. Both cooked by your hand, of course.", sourceObjective = "Personally cook and deliver a Sunrise Omelette and Prowler Steak to Devon Woods  in front of the New Avalon inn.", progress = "Back with my meal?", completion = "<Without skipping a beat, he takes a bite out of both dishes.>\n\nOh wow, Carrie's got competition. She must have trained you up on all of her techniques. I'm surprised, I have never been able to convince her to teach me anything.\n\nThanks. I've already marked your name down as a permanent VIP member of our establishment. You can come and go freely and without that membership card in hand, as long as you don't do anything to scare off our guests.", sourceObjectiveStatus = "unverified-source-field" }
quests[89381] = { id = 89381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pin Cushion", description = "Whoa! Awfully brave to be stomping around the shooting grounds amidst our training. You're practically begging for a projectile to the knee, or maybe your behind given the way you're shuffling around.\n\nBut hey, your safety is your prerogative. Since you seem like a real risk taker, why not lend us a helping hand? Gathering our arrows after every round of shots takes away from precious shooting time.\n\nHow about you go grab a few for me, eh?", sourceObjective = "Fetch arrows in the archery range south of the New Avalon town square. You may also acquire arrows when fighting rangers.", progress = "Those arrows won't fetch themselves. What are you waiting for?", completion = "Still alive, I see! Watching you dart around the range brought me a few laughs. I will admit, I expected you to scurry away when they started shooting right at you. \n\nThanks for giving my archers a moving target to practice with. I didn't think you would be stupid enough to try it, so I didn't have a reward in mind.\n\nHmm. How about I teach you how to craft a quiver? It'll make your job easier next time.", sourceObjectiveStatus = "unverified-source-field" }
quests[89421] = { id = 89421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bullet Heaven", description = "You might be thinking, \"but what if I wanted an ammo pouch instead,\" and \"if I say something, will she make me stand in front of bullets too?\" I can't read your mind, but a good ranger is great at making predictions.\n\nTruth is: we don't use bullets around here, despite my advocacy of such. Were a pile of bullets to, say, land at my feet, I suppose I would have no choice but to design a proper pouch to contain them.\n\nIf only.", sourceObjective = "Craft or purchase Thorium Shells from a player with the Engineering profession and bring them to Kyndra Swiftarrow near the New Avalon archery range.", progress = "Ho-hum! If only someone would deliver unto us a stockpile of bullets! That sure would be swell.", completion = "Ah, you're back and with an ample supply of bullets. You're great at dodging projectiles AND taking hints! I'm proud of you.\n\nSince you were willing to put your life at risk to recover some shoddy training arrows, I figured you would be back after being given a trivial task. I have already taken the time to design a proper pouch.\n\nI still have to convince my commander to invest in guns, but at least now I have some ammunition.", sourceObjectiveStatus = "unverified-source-field" }
quests[89442] = { id = 89442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emblem of Darkness", description = "There is one final piece; the Emblem of the Ashbringer. In a way, the emblem is the heart of the blade. Highlord Alexandros himself used all his will and determination to transfigure an orb of pure void into a vessel of the Light itself. \n\nThe emblem endured when Caldoran fell and the blade shattered. Adventurers recovered it and passed it into Lord Maxwell Tyrosus's care. \n\nRetrieve the emblem and we'll have everything we need for the next step.", sourceObjective = "Speak with Lord Maxwell Tyrosus at Light's Hope Chapel about the Emblem of the Ashbringer.\n\nProvided item:", completion = "<Lord Maxwell Tyrosus' eyes widen as you tell him of the Will of the Ashbringer.>\n\nThat is an incredible tale, {name}. Part of me rejoices at the prospect of restoring the blade and seeing my old friend finally find the peace that was stolen from him. However, there is a feeling that I just can't shake. I fear that this path won't lead you to the ending we'd hope for. \n\nRegardless, if you are sure that this is the way, then I will entrust the emblem to your care and pray for a hopeful outcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[89443] = { id = 89443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falling Into Place", description = "Here is the emblem. I warn you, do not touch it with your bare hand. It exudes a foul necromantic aura that could cause great harm. \n\nI wish you the best in this endeavor, {name}. I will dare hope for your success, but I will prepare for a less favorable outcome.", sourceObjective = "Combine the Reforged Blade of the Ashbringer, the Emblem of the Ashbringer, and the Hilt of the Ashbringer, and then speak with the Will of the Ashbringer to determine your next steps.", progress = "We are close now, {class}.", completion = "The pieces are falling into place. The weapon is completely inert now, but there's one final step needed to restore the blade's lost power. This next part won't require strength of arms, but it may still prove difficult.\n\nTell me, {class},  what do you know of Nordrassil, the World Tree?", sourceObjectiveStatus = "unverified-source-field" }
quests[89444] = { id = 89444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corrupted Emblem", description = "<Sifting through the ruins of the battle with Baelin Caldoran, you find the emblem from the shattered blade of the Ashbringer. As you hold the skull-shaped icon in your hand, you can swear you hear a slight,  murmuring whisper. You look around, searching for a source for the voice, but you see no obvious source of the sound. You shake your head and stow the emblem in your pack.>\n\nSeek out Lord Maxwell Tyrosus once you make your return to Light's Hope Chapel. He will be interested in this artifact.", sourceObjective = "Take the Corrupted Emblem to Lord Maxwell Tyrosus in Light's Hope Chapel in the Eastern Plaguelands.", progress = "Lord Maxwell Tyrosus tenses up as you show him the emblem you recovered.", completion = "When Alexandros set out to forge the Ashbringer, he did so with his heart filled with hope and the will to protect his homeland. \n\nIn the end, the blade was consumed by darkness, just as the wielder was. While Caldoran sought to cleanse it through domination and an abhorrent abuse of the light, he failed utterly to understand the nature of redemption itself. Redemption is of the heart and must be earned, not forced.\n\nI will keep this safe for now. Thank you, {class}. Now, we celebrate our victory.", sourceObjectiveStatus = "unverified-source-field" }
quests[89445] = { id = 89445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blades of Light", description = "Even ruined and broken, the properties of the blade you hold before you are impressive. If you could better understand the material that this blade was crafted from, it might be possible to create a truly exceptional weapon from it. First, you'll need to find a blacksmith skilled enough to ascertain its properties, and find a way to work the material.", sourceObjective = "Find a Blacksmith that can tell you more about the Ruined Lightforged Blade.", progress = "Eh? Canna spare a moment to flap jaws with ye! These breastplate's ain't gonna hammer themselves!", completion = "Oooh! If that isn't an impressive blade ye got there! \n\nYe say yer lookin fer someone to try and work the material? Hmm, well, I regret to tell ye that unlockin' the secrets of this metal is likely out of my depth. If only Omarion were here. He was the resident master craftsman here, and he were a right fine expert on exotic materials and alloys. He'd be perfect for summat like this. Only problem is, he up and vanished!  \n\nIf he's alive somewhere, he'd be yer best bet!", sourceObjectiveStatus = "unverified-source-field" }
quests[89446] = { id = 89446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Craftsman", description = "<Crafter Wilhem seems unable to assist you but he suggested that his former master, a man called Omarion, could. Should you find him, he might know more about this material.>", sourceObjective = "Find Master Craftsman Omarion.", progress = "<Omarion stares past you blankly.>", completion = "I see how it is. No one comes looking for me unless they need something. It's fine, it's fine. I don't need rescuing anyway. I'm content to just die here in this light-forsaken place. Please, just leave me to it.", sourceObjectiveStatus = "unverified-source-field" }
quests[89447] = { id = 89447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extravagant Tastes", description = "So you've got a very fancy chunk of metal there. Who cares? \n\nOh, you want me to tell you more about it? Well, it's a sword, and it's broken. Are we done now?\n\n<Omarion glares at you and then sighs heavily when it becomes evident you aren't going to walk away.>\n\nFine. Leave the blade with me and I'll take a look at it. While I'm at it, I could use a bite to eat. I used to know this goblin, Dirge Quickcleave. He makes the best chimaerok chops. Bring me some.", sourceObjective = "Bring ten servings of Dirge's Kickin' Chimaerok Chops to Master Craftsman Omarion in Naxxramas.", progress = "Turns out, when your captors are undead, feeding you isn't their highest priority. Not that I care; I was content to starve to death here. Since you won't stop pestering me, though, I suppose you could at least bring me a good final meal.", completion = "That hit the spot, {class}. \n\nSo about this blade. It is... actually quite remarkable. It radiates heat; and the blade holds an edge almost supernaturally well, It also seems to repel the undead, as evidenced by the fact that I've not had one single zombie wander by and try to eat me since you left it here. \n\nA pity, really. Zombies aren't great conversation, but you take what you can get in a place like this.", sourceObjectiveStatus = "unverified-source-field" }
quests[89448] = { id = 89448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Light", description = "<Omarion seems significantly more animated than when you first encountered him.>\n\nOkay {class}, you've got my attention. This metal is extremely unique, and I'd like to experiment with it some more. However, I'll need additional samples of the raw material. Bring me a dozen or so more ingots of this \"lightforged\" iron. Also, try to learn more about where these weapons are being created. A smith is only as good as his tools and his crafting space, after all.", sourceObjective = "Bring 12 ingots of Lightforged Iron to Master Craftsman Omarion in Naxxramas and discover where the Scarlet Crusade is forging these new weapons.", progress = "I really wish that I had some Kaja'Cola to go with these chops. Oh, you've never heard of Kaja'Cola? Well, if you ever get a chance to try some, it'll change your life.", completion = "These should do nicely. What else did you learn from your trip? \n\n<You tell Omarion about the Radiant Forge that you found within the Scarlet Enclave.>\n\nVery interesting. So there's a light-fueled anvil inside the Scarlet Enclave, and that's where they craft these weapons?\n\nWell, there's nothing for it. I'll need to see it for myself. I guess I'll take a rain check on dying alone in this awful place.", sourceObjectiveStatus = "unverified-source-field" }
quests[89449] = { id = 89449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Radiant Forge", description = "So, it seems like it's a bit of a mess over at Tyr's Hand. That's unfortunate, but the bottom line is that I need to get a good look at the workshop where they've been crafting these armaments. Otherwise I won't have any hope of unlocking this metal's secrets. \n\nJust mark the location of this workshop on my map and I'll make my way there after the coast is clear.", sourceObjective = "Enter the Scarlet Enclave and meet Master Craftsman Omarion at the Radiant Forge there.", completion = "I've been studying this workspace and I think I have a solid understanding of what the Crusade has been doing here. We should be able to use this material to make a blade of unparalleled quality. \n\nHowever, this lightforged iron on its own has a fatal flaw that significantly reduces its durability. It'd be perfect if we could use it as part of an alloy, though. \n\nJust to prepare you though, this could get expensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[89451] = { id = 89451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey To Moonglade", description = "I suggest you start in Moonglade, the Cenarion Circle stronghold. It was Archdruid Malfurion Stormrage that ordered the way shut, but not all of the druids agree with this. Some may be willing to assist you.\n\nYou are resourceful and I am confident you can overcome this obstacle. Gain access to the summit and speak to me again.", sourceObjective = "Find a way to reach the summit of Mount Hyjal.", completion = "You want to travel to the world tree? My mother had recent dealings there... until she went missing. That's why I am here and want an audience with the Cenarion Circle's leadership. That is my concern, not yours, though. \n\nThe wards barring Hyjal aren't what they used to be. You can't go through them, you may be able to go over them. I know someone who may be willing to give you aid.", sourceObjectiveStatus = "unverified-source-field" }
quests[89462] = { id = 89462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Druid of the Talon", description = "I have a passing acquaintance with a Druid of the Talon that might be willing to help you. The shrine of Aviana is on the slopes of Mount Hyjal and is sacred to her order, so they still have limited access to the mountain.\n\nHer name is Thisalee Crow. I believe that she regularly visits Everlook in Winterspring to trade for supplies. She's headstrong and very impulsive, which might just be exactly what you need for your quest. \n\nGood luck, {class}.", sourceObjective = "Speak with Thisalee Crow near Everlook in Winterspring.", completion = "<Thisalee listens intently as you tell her your story.>\n\nSo, let me get this straight; you want to go to the very top of Hyjal and harness the powers of the Well of Eternity to temper a broken, cursed, legendary sword? You want to do this so that you can remove said curse, and free its former owner from undeath? That... sounds kind of awesome actually.  \n\nI think I can help, but I've also got a few problems of my own that need resolving--if you don't mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[89463] = { id = 89463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nondisclosure Arguement", description = "I am not the type of goblin to share his secrets with some random adventurer, but I AM the type to share a gnome's! I happened to procure a few schematics on my way out here and am working on correcting the shortcomings in their designs. They still use safety fuses! Can you believe that? SAFETY FUSES!!\n\nAnyway, I am eager to share my progress, but I need a quill if I am going to scribble out all this junk. And I could use a cozy space so I can do some thinking. What do you say?", sourceObjective = "Fizzlefuse in New Avalon has requested a quill and something to make his hideout more comfortable. A Classy Quill can be found in the New Avalon Town Hall, and a House Prop may be found somewhere near Scholomance or in the Karazhan Crypts.", progress = "Hey, it's you! I can't wait to see what you've brought me.", completion = "You know, I'm not sure what I expected, but it wasn't... this. I suppose it matches the trees. I shouldn't complain, mostly because I would start yelling by the time I am through, and neither of us wants that.\n\nMore importantly, a quill! Forgot to mention I'm out of ink, but motor oil should do the trick.\n\n<Fizzlefuse tests the usability of the quill with a haphazardly drawn schematic.>\n\nHere you go, pal.", sourceObjectiveStatus = "unverified-source-field" }
quests[89471] = { id = 89471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Tinkering", description = "I think it's safe to say our business relationship is already firmly established. I am the brains, you are the brawn. That's great, because I realized about thirty seconds ago that I am missing some critical components!\n\nHere's a list of things I need based on these schematics, excluding all the gnomish garbage. I'll get these designs fixed up in the meantime. When you're back, we can get straight to work.", sourceObjective = "Fizzlefuse in New Avalon has provided a shopping list of Engineering components needed for his inventions. Bring these items back to him.", progress = "Took you a while, I was starting to think those Scarlet Crusaders finally did you in. Did you get everything I asked for?", completion = "I should have known you would conveniently ignore the grocery list. How is a goblin supposed to get a bite around here? Whatever.\n\nYou will be pleased to know that I finished the schematic for my newest invention: the Tinkerbox! This device is innocuous on its own, but that's the whole point! All you need to do is cram a few carefully calibrated parts into the back panel and then, when you're ready, press the big red button!\n\nWhat will happen? That's what you're about to find out!", sourceObjectiveStatus = "unverified-source-field" }
quests[89473] = { id = 89473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Well of Eternity", description = "We are close now. The cataclysmic destruction that the ancient Kaldorei spirits wrought upon the demon lord Archimonde took a terrible toll on the tree. The explosion scattered a myriad of debris in the area.\n\nGather fragments of Nordrassil from beneath the tree's boughs.  We will use that to create a special fire in which to heat the blade, before quenching it in the waters of the well itself. The magic will harden and bind the blade, restoring the magic that left it when it was shattered.", sourceObjective = "There is an abandoned druid camp on the south side of the well of eternity. Gather 12 pieces of Nordrassil Detritus scattered around the base of the world tree and place them inside the Hyjal Bonfire to ignite the flame.", progress = "The bonfire before you looks like a perfect place to heat the blade.", completion = "The Nordrassil branches you've gathered are now neatly arranged on the remnants of the bonfire. All that remains is to set it alight.", sourceObjectiveStatus = "unverified-source-field" }
quests[89474] = { id = 89474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgiveness", description = "Alexandros Mograine was murdered by his son and the weight of that betrayal is a shackle around his very soul. The Ashbringer was as much the man as the sword itself, and the blade will not find peace until the spirit of Alexandros himself does. Take the weapon to the Scarlet Monastery cathedral in Tirisfal Glades. Once there confront Mograine's son, the Scarlet Commander. \n\nMograine must find the will to forgive for this to truly end.", sourceObjective = "Travel to the Scarlet Monastery in Tirisfal Glades. Enter the monastery's cathedral while wielding the Corrupted Ashbringer and bear witness to what occurs there.", completion = "<The spirit doesn't speak, and indeed seems not even to notice your presence.> \n\n<Your heart sinks at the implications of what just happened. What will become of Alexandros now? What of the redemption of the Ashbringer? You have so many questions, and even fewer answers.> \n\n<Attempts to call upon the Will of the Ashbringer using the blade are only met with silence now.>", sourceObjectiveStatus = "unverified-source-field" }
quests[89475] = { id = 89475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lonely Path of the Damned", description = "<The spirit standing before you shows no awareness of your presence. After a moment, you realize that Lord Maxwell Tyrosus will want to know what occurred here. You should return to Light's Hope chapel and speak with him.>\n\n<You suspect that the Argent Crusaders may not be too excited to see you carrying the Ashbringer in its current, twisted form. You may want to keep the blade out of sight when you approach.>", sourceObjective = "Speak with Lord Maxwell Tyrosus at Light's Hope Chapel. \n\nYou should stow the Corrupted Ashbringer in your bags, or else the members of the Argent Dawn may react with hostility upon seeing the tainted weapon.", completion = "<Maxwell Tyrosus sighs heavily as you finish your accounting of events at the monastery.>\n\nIt seems that Alexandros was not yet ready to find peace, and so the blade remains tainted. \n\nThe thing that truly breaks my heart is that just as you approached, I had a... feeling. It was like my old friend was here with me once again just as I remembered him. It's foolish, I know, to hope such a thing after all that's happened.\n\nGo. Take the blade from here. I will not suffer its presence.", sourceObjectiveStatus = "unverified-source-field" }
quests[89485] = { id = 89485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whimsical Horrors", description = "As much as I enjoy the thought of you being the test subject for all of my inventions, this one has me a little uncertain. It is supposed to simply warp you a few yards forward, but when I poked the first prototype with a stick, it disappeared completely and took the stick with it!\n\nI've made several adjustments since then, across multiple devices. I saw you mingling with the locals earlier, see if you can get them to try it out. Then maybe, if you're feeling brave, try it yourself.", sourceObjective = "Sneak behind New Avalon citizens while disguised and give them a Portiporter. Once you have sufficiently proven to yourself that it will not result in an instant death, try the device yourself to identify the problem Fizzlefuse referred to.", progress = "How goes the testing? As much as I don't care for these scarlet types, I would hate to discover that my device is causing agonizing deaths unrelated to combustion.", completion = "I'm... sorry?! Could you repeat that?\n\n<Fizzlefuse's eyes glaze over, not with horror, but simply boredom.>\n\nSo you're saying the device works, it just seems to be getting some interference? Why didn't I think of that the first time. It makes total sense. I have no idea how to fix it, but it makes sense.\n\nHere's the schematic, feel free tinker with it. I'm sure it's on the cusp of being the greatest short-range transportation device ever made.", sourceObjectiveStatus = "unverified-source-field" }
quests[89486] = { id = 89486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pinch of Gunpowder", description = "I just know you're most excited to hear about what I had planned for the gunpowder.\n\nHave you ever heard of Nitro Boosts? Not nitro boots; boosts. If you have, you're a liar, because they haven't been invented. Until now!\n\nI want you to have the honors of trying them out. All you need to do is add in a pinch of gunpowder right here and push the button. If you want to go even faster, add in a bit more!\n\nMake sure to traverse a variety of terrain before you return.", sourceObjective = "Arrive at the following locations in New Avalon within the time limit.", progress = "I've already started the clock, why are you still here?", completion = "Nice! You made it back in one piece and with minimal burns. I think we can both agree this trial run was a success, in fact I think we can improve this with even more gunpowder!\n\nThanks for all the data, I knew you wouldn't disappoint. Here's the schematic for your own Nitro Boosts. I insist that you keep your gunpowder usage on the low side, else I'd have competition.", sourceObjectiveStatus = "unverified-source-field" }
quests[89487] = { id = 89487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much Ado About Magnets", description = "Even with the supplies you gathered, I can only do so much without my workshop. I did come up with a plan, a genius one at that, to finally figure out how these strange magnetic fields work. I suspect with enough precision goblin engineering that I can create a way to keep the distance between two people at a perpetual minimum! Nobody will get away from me without a purchase ever again.\n\nTo test my theory, take this prototype and wave it around in New Avalon. With any luck, you might find something!", sourceObjective = "Use the Prototype Magnet throughout New Avalon to reveal and attract magnetic bits. When you have sufficiently proven Fizzlefuse's theory, return to him.", progress = "You know, it's refreshing working on something that doesn't have a significant chance of turning me into a pile of ash. Maybe the gnomes are onto something after all.", completion = "It worked!? I mean, it worked! Of course it worked... ugh, I should learn to always trust my gut.\n\nI started to suspect my theory was a dud. Instead of configuring the device to use opposite polarities, it is built to release a burst of energy with the same polarity. The result, I am guessing, is that it will repel things instead of attract them.\n\nOh well, back to the drawing board. Here's the schematic anyway, in case pushing people away aligns with your business strategy.", sourceObjectiveStatus = "unverified-source-field" }
quests[89488] = { id = 89488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Kind of Peace", description = "I am using most of my waning strength to appear to you.\n\nThere is one fleeting hope. You may not be able to save the man, but you may still bring him some measure of peace by limiting the harm he can inflict. Mograine has returned to Naxxramas to recover and resurrect the horsemen. When that's done, his fury will be terrible.\n\nIt is wrong to ask this of you after all you've done... but please, confront the Spirit of Mograine. Do what you can to stop him, if only for now. I can help you reach him.", sourceObjective = "The Will of the Ashbringer is using the last of its power to create a connection to Alexandros Mograine inside of Naxxramas. Take the portal and confront the Spirit of Mograine.\n\nShould you fall in battle, make your way back to the portal within Light's Hope Chapel to re-enter Naxxramas.", progress = "<The spirit before flickers in and out of existence. It doesn't have much time left.>", completion = "It is... done-- for now. I can feel this form... beginning to fade. Thank you--{class}. The blade... remains corrupted but... perhaps... there is another who can... \n\nIn the meantime... keep it safe.  \n\nBefore I... fade completely--one small glimmer of light remains... that I can give...", sourceObjectiveStatus = "unverified-source-field" }
quests[89489] = { id = 89489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Increased Drop Rate", description = "Now that we know my inventions work as stand alone devices, the next logical step in innovation is to improve reusability and quality of life! I don't think either of us wants to throw a fist full of gold away each and every time we want to port over a puddle.\n\nAs always, I have an idea.\n\nBelts are a woefully underappreciated piece of equipment, and are convenient to reach. It makes sense to enhance these with reusable gadgets, but I need a few to practice with. Go steal a few.", sourceObjective = "Fizzlefuse in New Avalon has requested lots of belts, for good reason. Soldiers of New Avalon are a likely source of belts.", progress = "I am all set to begin tinkering the moment you bring me back some belts.\n\nWhat? No, I am not going to use my own!", completion = "While you were away, I managed to finish ALL THREE of my schematics for the belt tinkers! That's both very impressive for me and quite depressing for you.\n\nI also realized that we're very lucky our chaos hasn't earned us more attention from these pesky humans. As such, I don't think I need these belts at all, my focus now is going to be plotting my escape. I'll still take them anyway to start a collection; wouldn't want to get caught with my pants down.", sourceObjectiveStatus = "unverified-source-field" }
quests[89491] = { id = 89491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Complicated Escape Plan", description = "Well, it's been fun, but I think we have overstayed our welcome. I thought about using my new gadgets to get out in a pinch, but I can't carry all my new stuff in one trip!\n\nWhen I arrived here, I managed to get a transporter pad setup as you have seen. All it needs is some calibration.\n\nTake this device and use it near the gates, archery yard, and inside the tavern. Then and only then, stand on top of my teleporter and use your Gadgetzan or Everlook teleporter to kick it into gear.", sourceObjective = "Use the Triangulation Samophlange at three inconvenient locations and then use your Ultrasafe Transporter: Gadgetzan or Dimensional Ripper - Everlook while standing atop the teleportation pad to complete calibration. Then return to Fizzlefuse in New Avalon.", progress = "Already got most of my things packed up. Once you've completed the calibration, I am out of here!", completion = "You're back in one piece and the teleporter is purring like an orc! Goblin ingenuity at its finest.\n\nHey so, uh, I was so excited to get this going that I forgot to hand over the schematic for an easy return trip on your way out. No hard feelings, right?\n\nAnyway, it's all set for return trips once you get your own module assembled. As for me, I'm going to finish packing up and head back. Feel free to hit me up for parts in the meantime.\n\nThanks for all the help!", sourceObjectiveStatus = "unverified-source-field" }
quests[89562] = { id = 89562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Old Enemy", description = "I had heard that Caldoran was present at Naxxramas and I feared that if the battle turned, I'd be forced to the front lines alongside of him.\n\nWhile the Argent Dawn is in support of you providing aid to the Scarlet Reclamation forces, I must warn you in the most strenuous terms; be wary of Baelin Caldoran. My hands shake with rage even thinking about that man and the atrocities he has visited on the innocent. He is NOT to be trusted. Please, I implore you, heed my words here.", sourceObjective = "Learn more about Baelin Caldoran from Leonid Barthalomew the Revered.", progress = "Caldoran is not to be trusted, ever.", completion = "That's all I will say on the matter for now. It took me years to crawl out of the pit of darkness inside my soul after what that man did to me.\n\nWe may be tentative allies now, but I will see Caldoran pay for his crimes... someday. My oath on this holds. In the meantime, be extremely careful in your dealings with him.", sourceObjectiveStatus = "unverified-source-field" }
quests[89563] = { id = 89563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leonid's Burden", description = "I could not help but overhear your conversation with Leonid about Inquisitor Caldoran. The scant details Leonid provided to you are the barest sliver of the history they share and the suffering Caldoran has inflicted on him. I was there when Leonid was at his lowest point and I helped him find the strength to pick himself back up. \n\nI fear what our continued cooperation with the Scarlet Crusade will do to Leonid, particularly if it brings him closer to that man.", sourceObjective = "Receive instructions from Lord Maxwell Tyrosus.", completion = "I'll keep my good eye on things here, and you keep an eye firmly fixed on Caldoran while you are working with the reclamation forces. I do not trust any of our \"allies\" and I trust him least of all.\n\nSpeak with Leonid again. I have a mission that I've asked him to undertake and I'd like for you to accompany him. I think it would do him some good to have a distraction away from here.", sourceObjectiveStatus = "unverified-source-field" }
quests[89567] = { id = 89567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrecked Caravan", description = "Lord Tyrosus has asked me to investigate the remnants of a Scarlet Crusade caravan in Plaguewood along the road to Stratholme. \n\nRecent reports tell of extensive crusade movements all across the plaguelands leading up to the schism at Tyr's Hand, and this caravan may be able to provide us with some indication as to their purpose. \n\nI'll meet you there and we will investigate this together.", sourceObjective = "Investigate the remnants of the scarlet caravan in Plaguewood, along the road to Stratholme and speak with Leonid Barthalomew the Revered there when you have learned more.", progress = "There's definitely something strange about all of this. Did you find anything of interest?", completion = "So this caravan contained... plague samples taken from Naxxramas? But why? To what end? Was the Scarlet Crusade trying to study the plague to combat it?", sourceObjectiveStatus = "unverified-source-field" }
quests[89568] = { id = 89568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something New", description = "I think we need to learn more about this new plague. This seems to be targeted at... killing the undead and the living? The undead are naturally immune to the plague of undeath, being of said plague to begin with. If what I suspect is true, this might be something new and terrible. \n\nI am loathe to subject the undead here to more torment, but we must learn more before we return to Light's Hope.", sourceObjective = "Use the New Plague Samples on weakened Cannibal Ghouls, Stitched Horrors, Cursed Mages, Scourge Soldiers and Scourge Warders found throughout Plaguewood and observe the effects.", progress = "Being this close to Stratholme is unsettling to me after...\n\n<Leonid Barthalomew the Revered pauses while looking in the direction of Stratholme and you notice that his hand starts to tremble slightly.>\n\n...nevermind, it's nothing. \n\nLet's conclude our business here quickly, {name}.", completion = "The effect these plagues have on the undead are profound and terrifying. If these were to be turned against the forsaken in the ruins of Lordaeron, well, it could  be catastrophic.\n\nThere's one other test we need to perform.", sourceObjectiveStatus = "unverified-source-field" }
quests[89574] = { id = 89574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servants of Death", description = "To me, there is nothing more low than the living agents of the lich king. I disdain and reject those with the free will to see right from wrong, yet who choose to willingly serve death. Take the plague samples once again and test them on the living Cult of the Damned members nearby.\n\nDo not pity these monsters nor show them mercy. They've thrown in their lot with the damned, so damned they shall be.", sourceObjective = "Use the New Plague Samples on the Dark Summoners and Necromancers found throughout Eastern Plaguelands and observe the effects.", progress = "I've been studying these research notes, and what I am seeing is terrifying. \n\nThe Scarlet Crusade developed this plague.", completion = "It is exactly as I expect, this plague has similar effects on both the living and the dead. This bodes ill for all, I am afraid. \n\nThe question I have is; how were the Scarlet Crusaders able to develop such a plague? This would require a deep understanding of the original plague of undeath and research into such plagues is... challenging for the living. This is most troubling.\n\nI suspect we've learned what we can here for now. Before we head back however... could I ask a favor of you?", sourceObjectiveStatus = "unverified-source-field" }
quests[90107] = { id = 90107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blade Reformed", description = "I think I've got the alloy to a point here we can reliably use it to craft a blade's billet. Fortunately, we also have plenty of raw materials with everything you've gathered for me so far. \n\nStand back if you would. Working the forge can be... dramatic.", sourceObjective = "Stand back as Master Craftsman Omarion attempts to craft the Reforged Blade of the Ashbringer.", completion = "It's done. While my lightforged alloy is a product of holy magic, this blade in its current form is just that; a simple blade. Putting the rest of the pieces back together is on you and your ghostly friend. \n\nI haven't felt this accomplished in a while, but I have to confess that I have a bad feeling about all of this. I wonder if maybe it would have been better to let the Ashbringer stay broken. This feels wrong, like maybe this wasn't supposed to happen.", sourceObjectiveStatus = "unverified-source-field" }
quests[90116] = { id = 90116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holy Threads", description = "This loom is special. Did you know that? All of our craftsmen had their tools of the trade blessed by our high priests.\n\nIn particular, the loom attracts stray fabrics and thread destined to be used in the holiest of our ceremonial vestaments. Over time, we will have enough gathered to create a new robe, and these days are a cause for celebration, for me at least.\n\nIf you are interested in the process for your own curiosity, thread some bolts near the loom and watch the Light at work.", sourceObjective = "Acquire Dawnwoven Fabrics by weaving cloth into bolts while in close proximity to the Crusader's Loom. Return to Taylor once you have enough.", progress = "Normally it takes a few larger projects like shirts or trousers to accumulate enough dawnwoven fabric, but for the purposes of your demonstration I figure weaving bolts would be a simple enough task.", completion = "Magnificent! Of course this is just a small portion of a robe fit for a Scarlet abbot, but I imagine you now have a deeper appreciation toward your own craftsmanship.\n\nI will take this off your hands and store them away. The pattern for the sacred robes is a closely guarded secret, but I would like you to have this one instead. Deep and sturdy packs are a luxury these days, but well worth the investment. Who knows, maybe you can start a business selling bags?", sourceObjectiveStatus = "unverified-source-field" }
quests[90120] = { id = 90120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red is Not Dead", description = "Hm, speaking of secrets, I have been working on a new project: luxury packs for our highest ranking soldiers. They must be large, crafted from the finest silks, and most importantly, as red as the crest of the Scarlet Crusade.\n\nThe material is the easy part, I intend to use your dawnwoven threads for this. Finding the perfect dye, however, is well beyond my capabilities. Scour the world in search of the perfect red hue and I'll consider you a partner in this endeavor by sharing my final design with you.", sourceObjective = "Acquire a variety of materials that could be used as a vibrant red dye. red dye and Red Rose may be sourced from vendors. Firebloom may be acquired by Herbalists. Blood of Heroes can be found in the Plaguelands. Crimson Bladeleaves to extract dye from can be found near Lake Mennar in Azshara.", progress = "Take your time, truly. This is nothing more than a passion project of mine. I care far more about finding the most fitting red dye we can find than stocking these on my shelves, and I would rather you put that same care into your work than rush the job for my sake.\n\nI'll be here.", completion = "You have a natural eye for beauty! Not that I ever doubted you, but I didn't expect to immediately find a shade of red that would resonate so strongly with me. Yet, you brought me several!\n\n<Taylor admires the dye candidates one by one, unphased by the idea that one vial is full of blood.>\n\nThe ones labelled \"Blood of Heroes\" and \"Crimson Bladeleaf\" are my favorites, and it is a tough choice. I think it makes sense for the two of us to use different dyes, so I'll take the bladeleaf.", sourceObjectiveStatus = "unverified-source-field" }
quests[90506] = { id = 90506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Their Breath Away", description = "I've been working with Evie Whirlbrew to secure crucial supplies, but she is driving a hard bargain and refuses to budge. She insists that she'll only trade Nivifacient Glands from blue dragonspawn for them. This gland is what allows blue dragonkin to use their icy breath, and it has a variety of special alchemical properties. \n\nThere's a population of very hostile blue dragons at Mazthoril to the south and I could really use help obtaining some of these glands to use to satisfy this gouger.", sourceObjective = "Retrieve 10 Nivifacient Glands from blue dragonspawn at Mazthoril just south of Everlook.", progress = "I'd be lying if I said that I was entirely comfortable with extracting organs from living, breathing beings, even though they are very, very hostile. In any case though, we need these supplies and a druid has to do; what a druid has to do.", completion = "I think that the uh, less gory details I know about what went into extracting these, the better off I'll be. The blues aren't exactly forgiving. \n\nAnyway, I really appreciate this! I'm sure I can get those supplies from Evie now. Unless, of course, she decides to change the deal on me again!", sourceObjectiveStatus = "unverified-source-field" }
quests[90507] = { id = 90507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Logistics Challenges", description = "I have a longstanding arrangement with Azzleby to transport supplies through the mountain passes on his beasts of burden. Recently, his caravans have been getting raided by Winterfall Furbolgs and they've stolen our stuff! \n\nSearch the Winterfall encampments here in Winterspring for our missing supplies.", sourceObjective = "Gather 15 Crates of Moonglade Supplies from the Winterfall Furbolg camps and villages in Winterspring", progress = "I suspect the Winterfall furbolgs think that it's good fun to load up on firewater and ransack our caravans for sport. \n\nThat's just rude, if you ask me.", completion = "Thank you so much {name}. It's a huge relief to have these supplies back!", sourceObjectiveStatus = "unverified-source-field" }
quests[90508] = { id = 90508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As The Crow Flies", description = "I really should check in with Master Omnuron about this. However, you've been so helpful to the Druids of the Talon that I'll take a chance. I'm sure that he'll understand.\n\nIt's better to beg forgiveness than ask for permission anyway! \n\nWe'll leave now. You can't see the route we take to bypass the wards so I'll need to obscure your vision. This is irresponsible enough as it is and I definitely can't expose the secrets of the Druids of the Talon.", sourceObjective = "Secure transport to the peak of Mount Hyjal.", completion = "Well, here we are. \n\nI warn you, do not leave the immediate area of the summit. It will not go well for you. The druids that guard Nordrassil are not always what I'd call friendly. There's also a whole mountain full of other horrors up here that would love to make a meal out of a nice juicy {class} like you.\n\nI suggest you finish up here as quickly as possible and speak with me again when you are ready to head back down to Everlook. \n\nGood luck!", sourceObjectiveStatus = "unverified-source-field" }
quests[90510] = { id = 90510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Avalon", description = "As you've seen, New Avalon boasts a significant military presence but it also offers safety and security to civilians.\n\nIf you can cobble together a more permanent disguise, consider offering a helping hand. Ingratiating yourself with the folk there could be beneficial to our efforts to reclaim the enclave, to say nothing of putting you in a position to \"appropriate\" some of the material and resources there, enriching yourself and depriving their war machine of crucial supplies.", sourceObjective = "Use the Scarlet Insignia once you have acquired enough disguise pieces to fool the Scarlet Crusaders in New Avalon and speak with Inquisitor Jociphine again. Players with armor crafting professions can utilize recipes and plans for scarlet armor pieces obtained from hostile crusaders in Tyr's Hand and New Avalon.", progress = "If you are having trouble acquiring the pieces you need via crafting them yourself, perhaps strike a trade with others who have the proper skills and access to suitable designs and patterns.", completion = "Convincing enough, I suppose.\n\nNew Avalon lost some of its master craftsmen during a caravan run to Hearthglen a few years back, but I can see some of their designs were not lost.\n\nIf you haven't honed your own tradeskills much, you may have a harder time making headway in New Avalon. However, regardless or whether you know how to work a hammer or a needle, I suspect you may want to at least pay a visit to the quartermaster in the barracks. You might also be able to rummage around their storeroom.", sourceObjectiveStatus = "unverified-source-field" }
quests[90518] = { id = 90518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Apple a Day Keeps the Undead at Bay", description = "It is good to see you again. I have had no troubles keeping the kitchen stocked since you have been away, but I did notice this morning that I am just shy enough apples to make a pie. I thought it was time to give myself a little treat.\n\nIf you can spare a few minutes, could you stop by the orchard and grab a few? Unfortunately I still haven't made Johnny's pie yet either, but I can't make a pie without apples and I won't waste apples on Johnny's pie!\n\nI will, of course, share a slice with you.", sourceObjective = "Locate the apple orchard in the southern section of New Avalon to fetch some apples. Return to Carrie Hearthfire in the New Avalon inn once you have succeeded. If you find the apples to be too expensive, consider looking around for an alternative means to acquire them.", progress = "Remember that Johnny might want to charge extra for his best apples, but I'm sure you can find a creative solution if you don't want to line his pockets.", completion = "Delightful, I will get started immediately! These apples look even better than the last batch you delivered, it's almost as though you're trying to get on my good side...\n\n<As Carrie begins to set up her space to prepare the pie, she makes an exaggerated gesture that plainly displays her wedding ring.>\n\nThanks for stopping by and improving our evening's meal. Markus and I hope to see you again soon!", sourceObjectiveStatus = "unverified-source-field" }
quests[90519] = { id = 90519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish On Demand", description = "I hate fish. I cannot stand the smell of them. They are extremely creepy. Truly the worst.\n\nSince this is my kitchen, I can and do exercise my authority to say NO to fish imports, but sometimes our soldiers get it in their heads that they need a fisherman's feast.\n\nTonight is one of those nights it would seem. I need fish, on the double!", sourceObjective = "Investigate the boat docked south of New Avalon for a shipment of fish and return a haul back to Carrie.", progress = "Please don't deliver an incomplete order. I want to get it all out of the way at once.\n\nIf you can't get your hands on enough fish for the evening, maybe you can go scrounging for leftovers again. Truthfully I think that would be preferable.", completion = "Ah, I had hoped you had better things to do tonight but I suppose you have made yourself out to be quite dependable since we met.\n\nWell. I had better get started.", sourceObjectiveStatus = "unverified-source-field" }
quests[90520] = { id = 90520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Food Safety", description = "I seem to recall one of the ingredients that I sent you to collect when we first met was the meat. I also seem to recall a lot of complaints that night about their meals making them sick? It was the strangest thing.\n\nAnyway, the larder is running low on meats again and it would be nice to know that I have someone trustworthy to help replenish it. The last thing I need is to be expecting a delivery only to find out a week after the fact that the courier died!", sourceObjective = "Acquire meat that is safe for human consumption. If you struggle to locate some in New Avalon, you may (eventually) gather enough from slaying beasts in the Eastern Plaguelands.", progress = "Dinner is going to be running a little late at this rate.", completion = "Your commitment to consistency is incredible, my friend. These portions are expertly cut, and possess the same color and texture as your previous batch. If I ever find myself in a situation where I need to hunt for my own food, I hope to have you by my side.\n\nAnd Markus, of course.\n\nI will take these off your hands and get started. New Avalon will be eating good tonight!", sourceObjectiveStatus = "unverified-source-field" }
quests[90559] = { id = 90559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tempering", description = "<The branches of Nordrassil create a fire unlike anything you've ever seen. It almost seems to have a will and intelligence of its own. You can't be sure, but you could swear that the flame seems to have some awareness of your presence and regards you with a kind of curiosity.>\n\n<As unsettling as that is, all that remains is to heat the blade and plunge it into the waters of the Well of Eternity.>", sourceObjective = "Heat the Inert Ashbringer at the bonfire at the abandoned druid camp south of the Nordrassil, then quench the Heated Blade into the waters of the Well of Eternity. \n\nSpeak with The Will of the Ashbringer when you are done.", progress = "It is done. The blade is restored, though it still bears the taint of corruption.", completion = "You've done so much, but I must ask you to bear the blade to one final destination. \n\nOnce there, we can only hope that the soul of Alexandros Mograine has the courage to take the final step.", sourceObjectiveStatus = "unverified-source-field" }
quests[90560] = { id = 90560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familiar Foulness", description = "<You have found a vial of foul, viscous liquid on a laboratory table. It was surrounded by various ingredients that have been meticulously measured and diced into careful portions. Though the herbs are unidentifiable, one undamaged and discolored beast heart rests nearby.\n\nThe concoction is familiar, reminiscent of recent experiments performed by the Royal Apothecary Society. If your curiosity overpowers your disgust, perhaps one of their members may be interested in your discovery.>", sourceObjective = "Gather Discolored Beast Hearts from creatures in the plaguelands and then bring them and the Mishandled Healing Potion to an interested member of the Royal Apothecary Society in Undercity.", progress = "Hm? Do you have something for me?", completion = "Ah, hm, what a considerate offering, I suppose. Given some time and a few additional reagents I could probably solve whatever mystery you're looking to solve with this potion, but I have far more urgent matters to tend to at the moment. Sickly creature hearts are more Apothecary Renferrel's forte anyway.\n\nFortunately for you, I have been meaning to run an errand for Renferrel. Are you up for killing two humans with one plague? ...Metaphorically speaking, of course.", sourceObjectiveStatus = "unverified-source-field" }
quests[90566] = { id = 90566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, My Bleeding Hearts!", description = "I assume you are well acclimated to the Plaguelands given the impressive taint present on your specimens. It only stands to reason that you understand how inconvenient it is for any lone member of the Royal Apothecary Society to cross the Bulwark for supplies.\n\nRenferrel claims to have an interest in bleeding hearts, the flower, in addition to once-beating hearts. I am unsure whether it is for alchemical research or their visual appeal, but I know he would appreciate a delivery of various hearts.", sourceObjective = "Deliver the Basket of Discolored Beast Hearts and some Plaguelands Bleeding Hearts to Apothecary Renferrel in the Sepulcher of Silverpine Forest.", progress = "Am I expecting a delivery?\n\n<Apothecary Renferrel checks his notes.>\n\nYou don't look like the test subject I requested...", completion = "Oh. My bleeding hearts. After months of waiting for Faranell to come through, it finally arrives after I long since abandoned that research. Terrific.\n\nMy intrigue is piqued by what's in this basket of yours, however. I am reminded of the hearts from local worgs, except these appear to be much more durable against blight and corruption.\n\nHere, this recipe is inspired by an older concoction I developed in the past. Try it out and let me know how it goes.", sourceObjectiveStatus = "unverified-source-field" }
quests[90567] = { id = 90567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfamiliar Foulness", description = "<You have found a vial of foul, viscous liquid on a laboratory table. It was surrounded by various ingredients that have been meticulously measured and diced into careful portions. Though the herbs are unidentifiable, one undamaged and discolored beast heart rested nearby.\n\nAlchemists in Darnassus might have an idea of how to tap into whatever restorative properties might be present in the potion. You should also bring them some flowers, as to not come barreling into a shop with just a pile of hearts.>", sourceObjective = "Gather Discolored Beast Hearts and Bleeding Hearts from the plaguelands. Bring them and the Mishandled Healing Potion to an interested alchemist in Darnassus.", progress = "Ishnu-alah, traveler. Have you come to practice the art of alchemy or is there something else I can assist you with?", completion = "I almost suspected such, could you believe that you are not the first to show me this exact revelation? Were the implications not so dire, I would assume this is an elaborate practical joke at my expense.\n\nStudying the effects of the plaguelands, while often fascinating, is not practical due to its distance from home. Nonetheless I have made progress with previous samples provided to me, and would like to share my findings with you.\n\nPlease keep me in mind if you find more specimens.", sourceObjectiveStatus = "unverified-source-field" }
quests[90625] = { id = 90625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Dreaded Wings", description = "A shredded wing of the Dread Lord Balnazzar is all that remains of the toppled Nathrezim.\n\nSomeone at Light's Hope may be interested in this.", sourceObjective = "Take the Wing of Balnazzar to Light's Hope Chapel in the Eastern Plaguelands.", progress = "What brings you to Grok'lo?", completion = "A fellow trophy lover!? Grok'lo have large collection himself.\n\nNothing bring Grok'lo den together like skull of his enemy.\n\n<Grok'lo Laughs>\n\nWhat you got? Giant Bat wing? Mok'lo seen before. Not impressive anymore. Better as bow or sold for coin than a trophy.\n\nIf you like, bring Grok'lo a string and Grok'lo arrange a meeting with his special crafter.", sourceObjectiveStatus = "unverified-source-field" }
quests[90626] = { id = 90626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinew of Light", description = "Grok'lo will arrange a meeting with special crafter once you find a suitable string to go with that giant bat wing.\n\nGrok'lo recommend finding best string possible.\n\n<Grok'lo smiles under his helmet>\n\nDragon Sinew definitely best string.", sourceObjective = "Defeat Solistrasza and obtain a Mature Light Dragon Sinew, then bring it to Grok'lo at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Have you found a string to go with your bat wing?", completion = "Now that's a string! Grok'lo loves bright things!\n\n<Grok'lo nods>\n\nAh, no doubt in Grok'lo's head you'll get a lot of gold for this when it's made into a bow.", sourceObjectiveStatus = "unverified-source-field" }
quests[90627] = { id = 90627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafty the Crafter", description = "Alright, the name of my crafter, is Mizzle the Crafty.\n\nIt so obvious, even Grok'lo see it! Everyone think his name because he clever. NO! He Ogre, he no clever! It because he good at crafting!\n\n<Grok'lo nods>\n\nGo to Northern Dire Maul and meet with him. Make sure he not distracted with anything else when you meet.\n\nGo alone.", sourceObjective = "Meet with Mizzle the Crafty in Dire Maul North.\n\nYou'll want to catch him with no distractions, so don't kill any of the important Ogres on your way to him, or else he'll have to spend time replacing them and can't help you. \n\nGo alone.", progress = "Mister Mok'lo send you? If you big boss, he da second big boss, AND best customer.\n\nTribute chest always filled with spoils and gold from crafting for Grok'lo. We no ask where he get it all, but it belong to da Gordok now!\n\nOh, and now that you da new king, and me got nothing to fix up, I can help with smashing together whatever you need me to!", completion = "OH NOES! Mizzle put da bat wing and da pretty thread together!\n\nSmashed it a lot, but it need something else me no can do.\n\nDa Ogre Spirit told me it da lightness and da darkness of these two things. They don't get along. Ogre Spirit say it need a dash of Fate that can't be escaped. But me no know what that is.", sourceObjectiveStatus = "unverified-source-field" }
quests[91888] = { id = 91888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Delivery" }
quests[91889] = { id = 91889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Reward has Arrived!" }
